package com.onrender.smartnf.web;
import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.util.concurrent.*;import tools.jackson.databind.json.JsonMapper;
import com.onrender.smartnf.health.CurrentHealthMember;import com.onrender.smartnf.member.kakao.KakaoPrincipal;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
class MealAdditionTests {
 JdbcTemplate jdbc;Stub client;MealAdditionService service;JsonMapper json=new JsonMapper();
 static class Stub extends GeminiPeriodClient{int calls;String input,output;boolean fail;CountDownLatch entered,release;Stub(){super("test","gemini-3.5-flash-lite");}public String generateAddition(String input,Map<String,Object> schema){calls++;this.input=input;if(entered!=null){entered.countDown();try{release.await(3,TimeUnit.SECONDS);}catch(Exception e){throw new RuntimeException(e);}}if(fail)throw new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"provider unavailable");return output;}}
 @BeforeEach void setup(){var ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");jdbc=new JdbcTemplate(ds);jdbc.execute("CREATE TABLE recipe_library(recipe_id CHAR(64) PRIMARY KEY,recipe_data MEDIUMTEXT,period_kind VARCHAR(12))");client=new Stub();service=new MealAdditionService(jdbc,client,new DataSourceTransactionManager(ds));client.output=output("계란찜");}
 GeminiPeriodService.Criteria criteria(String... excluded){return new GeminiPeriodService.Criteria(false,false,false,false,null,null,"",List.of(excluded),Map.of());}
 List<MealAdditionService.Food> complete(){return List.of(new MealAdditionService.Food("새우 로제 스파게티","bowl",List.of("스파게티면 100g")),new MealAdditionService.Food("시금치나물","side",List.of("시금치 70g")));}
 MealAdditionService.Request request(String mode,String name){return new MealAdditionService.Request(mode,name,complete(),criteria(),true);}
 String output(String... names){return json.writeValueAsString(Map.of("candidates",Arrays.stream(names).map(name->Map.of("role","side","reason","함께 곁들이는 후보","recipe",new MyRecipeService.Snapshot(name,1,10,List.of("달걀 100g"),List.of("익힌다.")))).toList()));}
 @Test void completePastaAndSideStillReceiveNamedExtraFood(){var req=request("named","계란찜");var before=json.writeValueAsString(req.current());var r=service.recommend(1,req);assertEquals(1,r.candidates().size());assertEquals("계란찜",r.candidates().getFirst().recipe().name());assertEquals(before,json.writeValueAsString(req.current()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void namedRecipeIsReusedFromSharedDatabase(){service.recommend(1,request("named","계란찜"));var r=service.recommend(2,request("named","계란찜"));assertEquals("STORED",r.provider());assertEquals(1,client.calls);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void compatibleOffersUpToThreeFoodsWithoutWholeMealRoleRestrictions(){client.output=output("계란찜","두부구이","백미밥");var r=service.recommend(1,request("compatible",""));assertEquals(3,r.candidates().size());assertTrue(client.input.contains("새우 로제 스파게티"));assertEquals(3,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void excludedIngredientsAndInvalidAmountsNeverGetPublished(){for(String value:List.of("땅콩 100g","달걀 적당량","달걀 0g")){client.output=output("계란찜").replace("달걀 100g",value);var r=new MealAdditionService.Request("named","계란찜",complete(),criteria("땅콩"),true);assertThrows(ResponseStatusException.class,()->service.recommend(1,r));}assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void duplicateCurrentOrCandidateFoodsAreRejected(){for(String value:List.of(output("시금치나물"),output("계란찜","계란찜"))){client.output=value;assertThrows(ResponseStatusException.class,()->service.recommend(1,request("compatible","")));}assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void namedCandidateMustMatchRequestedFood(){client.output=output("두부구이");assertThrows(ResponseStatusException.class,()->service.recommend(1,request("named","계란찜")));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void invalidInputsFailBeforeGemini(){for(var req:List.of(new MealAdditionService.Request("named","",complete(),criteria(),true),new MealAdditionService.Request("compatible","",List.of(),criteria(),true),new MealAdditionService.Request("named","계란찜",complete(),criteria(),false),new MealAdditionService.Request("named","시금치나물",complete(),criteria(),true),new MealAdditionService.Request("named","땅콩볶음",complete(),criteria("땅콩"),true))){assertThrows(ResponseStatusException.class,()->service.recommend(1,req));}assertEquals(0,client.calls);}
 @Test void malformedNumbersAndStepsCannotBeCoerced(){for(int variant:List.of(0,1)){var tree=json.readTree(output("계란찜"));var recipe=(tools.jackson.databind.node.ObjectNode)tree.path("candidates").path(0).path("recipe");if(variant==0)recipe.put("servings",1.5);else recipe.putArray("steps").add(123);client.output=json.writeValueAsString(tree);assertThrows(ResponseStatusException.class,()->service.recommend(1,request("named","계란찜")));}assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void batchStorageRollsBackIfAnyRecipeFails(){jdbc.execute("ALTER TABLE recipe_library ADD CONSTRAINT reject_tofu CHECK(recipe_data NOT LIKE '%두부%')");client.output=output("계란찜","두부구이");assertThrows(Exception.class,()->service.recommend(1,request("compatible","")));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library",Integer.class));}
 @Test void providerFailureKeepsDatabaseAndCanBeRetried(){client.fail=true;assertThrows(ResponseStatusException.class,()->service.recommend(1,request("compatible","")));client.fail=false;assertEquals(1,service.recommend(1,request("compatible","")).candidates().size());}
 @Test void authenticatedControllerDeniesAnonymousAndUnregisteredUsers(){var controller=new MealAdditionController(new CurrentHealthMember(),service);assertEquals(401,assertThrows(ResponseStatusException.class,()->controller.recommend(null,request("named","계란찜"))).getStatusCode().value());var denied=new KakaoPrincipal("provider",null,"pending",List.of());assertEquals(403,assertThrows(ResponseStatusException.class,()->controller.recommend(UsernamePasswordAuthenticationToken.authenticated(denied,"",denied.getAuthorities()),request("named","계란찜"))).getStatusCode().value());assertEquals(0,client.calls);var member=new KakaoPrincipal("provider",1L,"member",List.of("USER"));var r=controller.recommend(UsernamePasswordAuthenticationToken.authenticated(member,"",member.getAuthorities()),request("named","계란찜"));assertEquals(200,r.getStatusCode().value());assertTrue(r.getHeaders().getCacheControl().contains("no-store"));}
 @Test void parallelDuplicateRequestsAreBounded()throws Exception{client.entered=new CountDownLatch(1);client.release=new CountDownLatch(1);try(var executor=Executors.newSingleThreadExecutor()){var job=executor.submit(()->service.recommend(1,request("compatible","")));assertTrue(client.entered.await(2,TimeUnit.SECONDS));assertEquals(409,assertThrows(ResponseStatusException.class,()->service.recommend(1,request("compatible",""))).getStatusCode().value());client.release.countDown();job.get(3,TimeUnit.SECONDS);assertEquals(1,client.calls);}}
 @Test void additionClientUsesOwnContractEvenOnJsonFallback(){var sent=new ArrayList<java.net.http.HttpRequest>();var c=new GeminiPeriodClient("test","gemini-3.5-flash-lite",r->{sent.add(r);return new GeminiPeriodClientTests.Reply(sent.size()==1?400:200,sent.size()==1?GeminiPeriodClientTests.error("responseSchema too complex"):GeminiPeriodClientTests.OK,r);});c.generateAddition("{}",MealAdditionService.schema());var body=json.readTree(GeminiPeriodClientTests.body(sent.getLast()));String instructions=body.path("systemInstruction").path("parts").path(0).path("text").asText();assertTrue(instructions.contains("mode=named"));assertTrue(instructions.contains("candidates"));assertFalse(instructions.contains("slots"));assertEquals(2,sent.size());}
}
